ga4I(){return"\u0639\u0631\u0636 \u0627\u0644\u0623\u0631\u0635\u062f\u0629 \u0641\u064a \u0643\u0634\u0648\u0641 \u0627\u0644\u0623\u0637\u0628\u0627\u0621"},
ga4H(){return"\u0625\u0636\u0627\u0641\u0629 \u0645\u0644\u062e\u0635 \u0625\u0644\u0649 \u0642\u0627\u0626\u0645\u0629 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629: \u063a\u064a\u0631 \u0627\u0644\u0645\u062f\u0641\u0648\u0639 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0643\u0634\u0641\u060c \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a \u0645\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0648\u0625\u062c\u0645\u0627\u0644\u064a \u0645\u0627 \u064a\u062f\u064a\u0646 \u0628\u0647 \u0627\u0644\u0637\u0628\u064a\u0628."},
ga3o(){return"\u062f\u0645\u062c \u0639\u064a\u0627\u062f\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0648\u0627\u062d\u062f \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a"},
ga3n(){return"\u0641\u064a \u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0637\u0628\u064a\u0628 \u0623\u0648 \u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u062f\u0641\u0639\u060c \u062a\u062e\u0637\u064a \u0637\u0628\u0627\u0639\u0629 \u0633\u0637\u0631 \u0645\u0646\u0641\u0635\u0644 \u0644\u0644\u0639\u064a\u0627\u062f\u0629/\u0627\u0644\u0637\u0628\u064a\u0628 \u0639\u0646\u062f\u0645\u0627 \u062a\u062d\u062a\u0648\u064a \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0639\u0644\u0649 \u0637\u0628\u064a\u0628 \u0648\u0627\u062d\u062f \u0641\u0642\u0637 \u0646\u0634\u0637."},
ga45(){return"\u0628\u0637\u0627\u0642\u0629 \u0627\u0633\u062a\u0644\u0627\u0645 \u0645\u0628\u0633\u0637\u0629"},
ga44(){return"\u0637\u0628\u0627\u0639\u0629 \u0628\u0637\u0627\u0642\u0629 \u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0641\u062d\u0635 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0628\u0627\u0633\u0645 \u0627\u0644\u0645\u0631\u064a\u0636 \u0648\u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0631\u0645\u0632 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629 \u0641\u0642\u0637 \u2014 \u0628\u062d\u062c\u0645 \u062b\u0627\u0628\u062a\u060c \u0644\u0644\u0635\u0642\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644\u0629 \u0643\u0645\u0644\u0635\u0642."},
ga4K(){return"\u0627\u062d\u062a\u0633\u0627\u0628 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u064f\u0633\u0644\u064e\u0651\u0645\u0629 \u0641\u0642\u0637 \u0643\u062f\u064a\u0646"},
ga4J(){return'\u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u0644\u0645 \u062a\u064f\u0634\u062d\u0646 \u0628\u0639\u062f \u0644\u0646 \u062a\u064f\u062d\u062a\u0633\u0628 \u0636\u0645\u0646 \u0627\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0639\u0644\u0649 \u0627\u0644\u062f\u0643\u062a\u0648\u0631 \u0641\u064a \u0627\u0644\u0643\u0634\u0641 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u060c \u0648\u0644\u0646 \u062a\u064f\u062f\u0641\u0639 \u0639\u0628\u0631 \u062f\u0641\u0639\u0629 "\u062d\u0633\u0628 \u0627\u0644\u062f\u0643\u062a\u0648\u0631"\u060c \u0625\u0644\u0649 \u0623\u0646 \u062a\u064f\u0634\u062d\u0646 \u0641\u0639\u0644\u064a\u064b\u0627.'},
