ga3Q(){return"\u0644\u0627 \u064a\u064f\u0637\u0628\u0639 \u0627\u0633\u0645 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0648\u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0645\u0634\u063a\u0651\u0644 \u0627\u0644\u0645\u0627\u0633\u062d \u0639\u0644\u0649 \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629 (\u0627\u0644\u0630\u064a \u064a\u0631\u0627\u0641\u0642 \u0627\u0644\u0639\u0645\u0644)\u060c \u062d\u062a\u0649 \u0644\u0627 \u064a\u0639\u0631\u0641 \u0627\u0644\u0641\u0646\u064a\u0648\u0646 \u0644\u0645\u0646 \u062a\u0639\u0648\u062f \u0627\u0644\u062d\u0627\u0644\u0629. \u062a\u0628\u0642\u0649 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0627\u0644\u0643\u0634\u0648\u0641\u0627\u062a \u0648\u062a\u0630\u0643\u0631\u0629 \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \u062a\u0639\u0631\u0636\u0647\u0627 \u0643\u0627\u0644\u0645\u0639\u062a\u0627\u062f."},
ga4p(){return'\u0634\u0631\u064a\u0637 "\u0625\u0639\u0627\u062f\u0629" \u0643\u0628\u064a\u0631 \u0639\u0644\u0649 \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629'},
ga4o(){return"\u064a\u064f\u0637\u0628\u0639 \u0639\u0644\u0649 \u0645\u0644\u0635\u0642 \u062d\u0627\u0644\u0629 \u0627\u0644\u0625\u0639\u0627\u062f\u0629 \u0634\u0631\u064a\u0637 \u0623\u062d\u0645\u0631 \u0643\u0628\u064a\u0631 \u0645\u0643\u062a\u0648\u0628 \u0639\u0644\u064a\u0647 \u0625\u0639\u0627\u062f\u0629 \u0645\u0639 \u0631\u0642\u0645 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u0635\u0644\u064a\u0629\u060c \u062d\u062a\u0649 \u064a\u0646\u062a\u0628\u0647 \u0627\u0644\u0641\u0646\u064a\u0648\u0646 \u0623\u0646\u0647\u0627 \u0625\u0639\u0627\u062f\u0629."},
ga4C(){return"\u0639\u0645\u0648\u062f \u0627\u0644\u0645\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0643\u0634\u0648\u0641 \u0627\u0644\u062d\u0633\u0627\u0628"},
ga4B(){return"\u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641: \u0644\u0627 \u064a\u0638\u0647\u0631 \u0639\u0645\u0648\u062f \u0627\u0644\u0645\u0627\u062f\u0629 \u0641\u064a \u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0643\u0634\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u064a\u0646."},
ga4f(){return"\u062a\u0645 \u062d\u0641\u0638 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0637\u0628\u0627\u0639\u0629."},
