gagv(){return"\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u0648\u0649"},
gah3(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0628\u0639\u062f \u2014 \u062a\u0639\u0645\u0644 \u0627\u0644\u0645\u0648\u0627\u062f \u062a\u0645\u0627\u0645\u064b\u0627 \u0643\u0645\u0627 \u0643\u0627\u0646\u062a \u062d\u062a\u0649 \u062a\u0636\u064a\u0641 \u0648\u0627\u062d\u062f\u064b\u0627."},
gahm(){return"\u0623\u062f\u0648\u0627\u0631 \u0627\u0644\u0645\u0633\u062d \u0644\u0644\u062a\u0631\u0642\u064a\u0629"},
gahl(){return'\u062d\u062f\u062f \u0627\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u062a\u064a \u064a\u0645\u0643\u0646 \u0644\u0643\u0644 \u062f\u0648\u0631 \u0645\u0633\u062d\u0647\u0627 \u2014 "\u0645\u0648\u0638\u0641\u0648\u0646 \u0622\u062e\u0631\u0648\u0646" \u064a\u0634\u0645\u0644 \u0623\u064a \u0634\u062e\u0635 \u0644\u0627 \u064a\u062d\u0645\u0644 \u0623\u064a\u064b\u0627 \u0645\u0646 \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0623\u062f\u0646\u0627\u0647. \u062a\u062d\u062f\u064a\u062f \u0623\u064a \u0645\u0631\u062d\u0644\u0629 \u0644\u062f\u0648\u0631 \u0645\u0627 \u064a\u062d\u0635\u0631 \u0630\u0644\u0643 \u0627\u0644\u062f\u0648\u0631 \u0641\u064a \u0645\u0631\u0627\u062d\u0644\u0647 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0641\u0642\u0637\u061b \u0643\u0644 \u0645\u0627 \u0639\u062f\u0627\u0647\u0627 \u064a\u0635\u0628\u062d \u0645\u0645\u0646\u0648\u0639\u064b\u0627 \u0639\u0644\u064a\u0647. \u0627\u0644\u062f\u0648\u0631 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u064f\u062d\u062f\u064e\u0651\u062f \u0644\u0647 \u0634\u064a\u0621 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646 \u064a\u0628\u0642\u0649 \u063a\u064a\u0631 \u0645\u0642\u064a\u0651\u062f \u062a\u0645\u0627\u0645\u064b\u0627\u060c \u0643\u0645\u0627 \u0647\u0648 \u0627\u0644\u062d\u0627\u0644 \u0627\u0644\u0622\u0646 \u2014 \u0641\u0639\u0651\u0644 "\u062d\u0638\u0631 \u0643\u0644\u064a\u064b\u0627" \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643 \u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0645\u0646\u0639 \u0647\u0630\u0627 \u0627\u0644\u062f\u0648\u0631 \u0645\u0646 \u0627\u0644\u0645\u0633\u062d \u0646\u0647\u0627\u0626\u064a\u064b\u0627.'},
